package dominoes

// Domino represents a single domino stone. The two elements are the number
// of dots on each half of the stone.
type Domino [2]int

// MakeChain tries to order the given dominoes so that they form a closed
// chain: the halves of neighbouring stones match, and the two halves that
// have no neighbour (the ends of the chain) match each other.
//
// It returns the ordered chain and true if a valid chain exists, or nil and
// false otherwise.
func MakeChain(input []Domino) ([]Domino, bool) {
	if len(input) == 0 {
		return []Domino{}, true
	}

	// A necessary condition for a closed chain: every value must appear an
	// even number of times across all stone halves.
	counts := make(map[int]int)
	for _, d := range input {
		counts[d[0]]++
		counts[d[1]]++
	}
	for _, c := range counts {
		if c%2 != 0 {
			return nil, false
		}
	}

	// Backtracking search: try each stone as the first one, in both
	// orientations, and extend the chain with stones that match its tail.
	used := make([]bool, len(input))
	for i := range input {
		used[i] = true
		for _, first := range orientations(input[i]) {
			if chain := build(input, used, []Domino{first}); chain != nil {
				return chain, true
			}
		}
		used[i] = false
	}
	return nil, false
}

// orientations returns the orientations of d, deduplicated for double
// stones, which look the same either way round.
func orientations(d Domino) []Domino {
	if d[0] == d[1] {
		return []Domino{d}
	}
	return []Domino{d, {d[1], d[0]}}
}

// build tries to extend the chain (whose next stone must match its current
// tail) with the remaining unused dominoes. It returns a completed closed
// chain, or nil if none can be built from this state.
func build(input []Domino, used []bool, chain []Domino) []Domino {
	if len(chain) == len(input) {
		if chain[0][0] == chain[len(chain)-1][1] {
			return chain
		}
		return nil
	}

	tail := chain[len(chain)-1][1]
	for i := range input {
		if used[i] {
			continue
		}
		d := input[i]
		// Normal orientation: the stone's left half must match the tail.
		if d[0] == tail {
			used[i] = true
			if chain := build(input, used, append(chain, d)); chain != nil {
				return chain
			}
			used[i] = false
		}
		// Reversed orientation: only meaningful for non-double stones.
		if d[1] == tail && d[0] != d[1] {
			used[i] = true
			if chain := build(input, used, append(chain, Domino{d[1], d[0]})); chain != nil {
				return chain
			}
			used[i] = false
		}
	}
	return nil
}

